<?php
require_once __DIR__ . '/_layout.php'; requirePermission('reservations.manage');
$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$notifications=dbFetchAll("SELECT n.*,r.reference FROM notifications n LEFT JOIN reservations r ON r.id=n.reservation_id WHERE n.agency_id IN ($ph) ORDER BY n.created_at DESC LIMIT 100",$ids);
backofficeHeader(t('nav.notifications'),'notifications.php');?><?php pageHeader('page.notifications.title', 'page.notifications.description', ['breadcrumbs'=>[['label'=>'nav.overview'],['label'=>'nav.notifications']],'primary'=>['label'=>'action.prepare_send','href'=>'notification_form.php']]); ?><div class="grid"><section class="card full"><div class="section-card-header"><h2><?=navigationIcon('bell')?><?=e(t('section.history'))?></h2></div><div class="table-wrap"><table><tr><th><?=e(t('field.created'))?></th><th><?=e(t('field.reservation'))?></th><th><?=e(t('field.channel'))?></th><th><?=e(t('field.recipient'))?></th><th><?=e(t('field.message'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($notifications as $n):?><tr><td><?=formattedDateTime($n['created_at'])?></td><td><bdi><?=e($n['reference'])?></bdi></td><td><?=e(t('option.'.$n['channel']))?></td><td><bdi><?=e($n['recipient'])?></bdi></td><td class="wrap-cell"><?=e($n['message'])?><?php if($n['channel']==='whatsapp'&&normalizedPhone($n['recipient'])):?><br><a target="_blank" rel="noopener" href="https://wa.me/<?=e(normalizedPhone($n['recipient']))?>?text=<?=e(rawurlencode($n['message']))?>"><?=e(t('action.open_whatsapp'))?><?=actionIcon('external')?></a><?php endif;?></td><td><?=statusBadge($n['status'])?></td></tr><?php endforeach;?></table><?php if(!$notifications)echo emptyState('empty.no_records');?></div></section></div><?php backofficeFooter();
